public partial class CommonMechanicsSuite {
 bool Need(string id)=>Wants(id)&&!Done(id);
 IEnumerator RunExtras(){
  if(Need("pickaxe")){Stage(site);SpawnTarget(site+Vector3.forward*1.6f);yield return Wait(1);yield return Take("pickaxe","Pickaxe / grip, movement and melee",PickaxeTake());Destroy(target.gameObject);target=null;}
  if(Need("weapon_rarity")){Stage(site);for(int i=0;i<5;i++)pc.me.inv.slots[i]=Item.Weapon(WeaponTable.Get("assault_rifle"),(Rarity)i);pc.me.inv.AddAmmo(AmmoType.Medium,300);yield return Wait(1);yield return Take("weapon_rarity","Five rarities / inventory, firing and ammo",RarityTake());}
  if(Need("loot")){Stage(site);var chest=LootContainer.All.FirstOrDefault(x=>x.chest&&!x.opened&&!x.supply);var ammo=LootContainer.All.FirstOrDefault(x=>!x.chest&&!x.opened&&!x.supply);var c=chest?Instantiate(chest.gameObject,new Vector3(site.x-3,Ground(site)+.2f,site.z+7),Quaternion.identity).GetComponent<LootContainer>():null;var a=ammo?Instantiate(ammo.gameObject,new Vector3(site.x+3,Ground(site)+.2f,site.z+7),Quaternion.identity).GetComponent<LootContainer>():null;WorldItem.Spawn(Item.Weapon(WeaponTable.Get("pistol"),Rarity.Uncommon),site+Vector3.forward*3);yield return Wait(2);yield return Take("loot","Floor loot, chest and ammo box",LootTake(c,a),"Two real container objects are cloned into an open presentation area before the take. Their ordinary opening and pickup code is unchanged.");}
  if(Need("inventory")){Stage(site);for(int i=0;i<5;i++)pc.me.inv.slots[i]=Item.Weapon(WeaponTable.All[i],(Rarity)i);var w=WorldItem.Spawn(Item.Weapon(WeaponTable.Get("pistol"),Rarity.Legendary),site+Vector3.forward*3);_slot=1;yield return Wait(2);yield return Take("inventory","Five slots / select, compare and replace",InventoryTake(w));}
  if(Need("elimination_loot")){Stage(site);Equip("assault_rifle");SpawnTarget(site+Vector3.forward*8);target.health=100;target.shield=50;target.inv.Add(Item.Weapon(WeaponTable.Get("shotgun"),Rarity.Epic));target.inv.Add(Item.Consumable(WeaponTable.Consumables[1],2));target.inv.AddAmmo(AmmoType.Shells,32);target.inv.AddMats(BuildMat.Wood,100);yield return Wait(1);yield return Take("elimination_loot","Elimination / dropped inventory and pickup",EliminationTake(),"A passive 100 HP / 50 shield target has a prepared inventory. Elimination comes from ordinary shots, with no match result forced.");if(target)Destroy(target.gameObject);target=null;}
  if(Need("mantle")){MoveShowcase.PickStart(out var start,out float yaw);var type=typeof(MoveShowcase);bool found=(bool)type.GetField("_hasLedge",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);if(found){var from=(Vector3)type.GetField("_ledgeFrom",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);var dir=(Vector3)type.GetField("_ledgeDir",BindingFlags.NonPublic|BindingFlags.Static).GetValue(null);Stage(from,Mathf.Atan2(dir.x,dir.z)*Mathf.Rad2Deg);Equip("assault_rifle");yield return Wait(1);yield return Take("mantle","Mantle / approach, climb and landing",MantleTake(dir));}}
  if(Wants("editing")&&(!Done("editing")||!Done("editing__floor")))yield return RecordEdits();
  if(Need("destruction")){Stage(site+Vector3.back*16);var baseSlot=BuildSystem.Compute(PieceType.Stairs,Feet,0,8);var first=BuildSystem.Place(pc.me,baseSlot,BuildMat.Wood);if(first){var s=BuildSystem.Compute(PieceType.Stairs,baseSlot.pos+Vector3.up*4,0,8);BuildSystem.Place(pc.me,s,BuildMat.Wood);var s2=BuildSystem.Compute(PieceType.Stairs,s.pos+Vector3.up*4,0,8);BuildSystem.Place(pc.me,s2,BuildMat.Wood);Equip("rocket_launcher");pc.Teleport(Feet+Vector3.back*8+Vector3.right*6,-20);_look=first.Center;yield return Wait(5);yield return Take("destruction","Rocket damage / support and cascading collapse",DestructionTake(first),"Three stairs are placed through the building API before the take; normal rockets destroy their support.");}}
  if(Need("supply_drop")){Stage(site);var d=SupplyDrop.Spawn(site+Vector3.forward*10,70);yield return Wait(.2f);yield return Take("supply_drop","Supply drop / descent, open and collect",SupplyTake(d));}
  if(Need("rift")){var r=Rift.All.FirstOrDefault();if(r){Stage(r.transform.position-Vector3.forward*6);yield return Wait(1);yield return Take("rift","World rift / enter, glide and land",RiftTake(r));}}
  if(Need("storm_map")){Stage(site);Match.I.startTime=Time.time-53;Match.I.storm=new Storm(1,782,p=>true);Match.I.storm.Update(53);Match.I.enabled=true;yield return Wait(1);yield return Take("storm_map","Storm boundary and map",StormTake(),"Storm clock is advanced before the take to avoid a long empty wait. Actual storm progression and damage continue during recording.");Match.I.enabled=false;}
  if(Need("replay")){Stage(site);Equip("pistol");yield return Wait(1);yield return Take("replay","Replay and free camera",ReplayTake());}
  yield return Advanced();
  if(Need("frontend")){Stage(site);pc.enabled=false;pc.cam.enabled=false;var lobby=Lobby.Show(FindFirstObjectByType<GameBootstrap>(),0);UiPointer.scripted=true;yield return Wait(3);yield return Take("frontend","Lobby / locker, outfits, emotes, career and settings",FrontendTake(lobby));}
 }
 IEnumerator PickaxeTake(){step="Idle and weapon grip";_look=target.Chest;yield return Wait(4);step="Melee swings";for(int i=0;i<5;i++){_tap=true;yield return Wait(1.2f);}step="Walk with the pickaxe";_move=new Vector2(.4f,0);yield return Wait(2);_move=new Vector2(-.4f,0);yield return Wait(2);_move=Vector2.zero;_look=target.Chest;yield return Wait(2);step="Second series";for(int i=0;i<4;i++){_tap=true;yield return Wait(1.2f);}yield return Wait(3);}
 IEnumerator RarityTake(){for(int i=0;i<5;i++){step=((Rarity)i)+" / fire and reload";_slot=i+1;yield return Wait(2);_tap=true;yield return Wait(.8f);reload=true;yield return Wait(2.5f);}}
 IEnumerator LootTake(LootContainer c,LootContainer a){step="Automatic floor pickup";yield return WalkTo(site+Vector3.forward*3,.5f,5);yield return Wait(3);foreach(var box in new[]{c,a}){if(!box)continue;step="Approach "+box.Label;_look=box.transform.position+Vector3.up*.5f;yield return WalkTo(box.transform.position,1.8f,6);yield return Wait(2);step="Open container";_interact=true;yield return Wait(3);step="Collect contents";foreach(var w in WorldItem.All.Where(w=>w&&Vector3.Distance(w.transform.position,box.transform.position)<4).ToArray()){if(!w)continue;yield return WalkTo(w.transform.position,.6f,2);}yield return Wait(3);}}
 IEnumerator InventoryTake(WorldItem w){for(int i=1;i<=5;i++){step="Inventory slot "+i;_slot=i;yield return Wait(3);}step="Full inventory / approach new item";_look=w.transform.position;yield return WalkTo(w.transform.position,1.8f,4);yield return Wait(3);step="Select a slot and replace with Interact";_slot=1;yield return Wait(2);_interact=true;yield return Wait(4);step="Inspect replacement and dropped item";_move=new Vector2(.35f,0);yield return Wait(2);_move=Vector2.zero;yield return Wait(3);}
 IEnumerator EliminationTake(){_look=target.Chest;step="Normal fire at passive target";_aim=true;for(int i=0;i<18&&target&&target.Alive;i++){_tap=true;yield return Wait(.45f);}_aim=false;yield return Wait(4);var at=target.transform.position;step="Dropped items, ammo and materials";yield return WalkTo(at,2,6);yield return Wait(4);foreach(var w in WorldItem.All.Where(w=>w&&Vector3.Distance(w.transform.position,at)<5).ToArray()){if(!w)continue;yield return WalkTo(w.transform.position,.5f,3);}yield return Wait(5);}
 IEnumerator MantleTake(Vector3 dir){step="Approach the real ledge";_move=Vector2.up;for(int i=0;i<180;i++){if(pc.moves.FindLedge(dir,.75f,2.3f,out var top)){_jump=true;break;}yield return null;}yield return Wait(2);_move=Vector2.zero;step="Standing on the ledge";yield return Wait(4);_look=Feet-dir*30+Vector3.up;yield return Wait(3);step="Walk off and land";_move=Vector2.up;yield return Wait(2);_move=Vector2.zero;yield return Wait(4);_look=Feet+dir*30+Vector3.up;yield return Wait(3);step="Second approach";_move=Vector2.up;for(int i=0;i<150;i++){if(pc.moves.FindLedge(dir,.75f,2.3f,out var top)){_jump=true;break;}yield return null;}yield return Wait(2);_move=Vector2.zero;yield return Wait(3);}
 Vector3 TilePoint(Destructible d,int index)=>d.transform.TransformPoint(PieceEdit.Tile(d.piece,index,.2f).center);
 IEnumerator EditTake(Destructible wall){foreach(int mask in new[]{PieceEdit.Window,PieceEdit.Door,PieceEdit.HalfWall}){step="Open edit grid";_look=TilePoint(wall,0);yield return Wait(1);_edit=true;yield return Wait(1.2f);for(int i=0;i<9;i++)if((mask&(1<<i))!=0){_look=TilePoint(wall,i);yield return Wait(.7f);_tap=true;yield return Wait(.4f);}step="Confirm edit";_edit=true;yield return Wait(2);step="Inspect opening";_look=wall.Center;yield return Wait(2);if(mask==PieceEdit.Window){_tap=true;yield return Wait(2);}step="Reset to full wall";_look=TilePoint(wall,0);yield return Wait(1);_edit=true;yield return Wait(1);_aimTap=true;yield return Wait(2.5f);}}
 IEnumerator DestructionTake(Destructible first){var foot=first.transform.position;step="Full structure and support";yield return Wait(5);_look=first.Center;_aim=true;yield return Wait(2);step="Rocket into support";_tap=true;yield return Wait(4);_aim=false;step="Observe cascading collapse";_look=foot+Vector3.forward*5+Vector3.up*4;yield return Wait(7);step="Walk towards debris";yield return WalkTo(foot,4,7);yield return Wait(5);}
 IEnumerator SupplyTake(SupplyDrop drop){step="Descent";for(int frame=0;frame<1800&&drop&&!drop.landed;frame++){_look=drop.transform.position+Vector3.up*1.5f;yield return null;}yield return Wait(3);var at=drop.transform.position;_look=at+Vector3.up*.5f;step="Approach and open";yield return WalkTo(at,2,7);yield return Wait(2);_interact=true;yield return Wait(4);step="Collect loot";foreach(var w in WorldItem.All.Where(w=>w&&Vector3.Distance(w.transform.position,at)<5).ToArray()){if(!w)continue;yield return WalkTo(w.transform.position,.6f,3);}yield return Wait(5);}
 IEnumerator RiftTake(Rift r){step="Approach the rift";_look=r.transform.position;_move=Vector2.up;yield return Until(()=>pc.mode==PlayerController.Mode.Skydive,5);step="Rift launch and glider";_move=new Vector2(.3f,1);yield return Wait(10);_move=Vector2.zero;yield return Until(()=>pc.mode==PlayerController.Mode.Ground,30);step="Landing and control restored";yield return Wait(4);_move=new Vector2(.3f,0);yield return Wait(2);_move=Vector2.zero;yield return Wait(3);}
 IEnumerator StormTake(){step="Full map / current and next circles";map=true;yield return Wait(8);map=true;step="Live HUD and storm timer";yield return Wait(15);step="Circle transition on the map";map=true;yield return Wait(18);map=true;yield return Wait(5);}
 IEnumerator ReplayTake(){step="Record movement and shots";_move=Vector2.up;yield return Wait(2);_move=Vector2.zero;_tap=true;yield return Wait(1);_tap=true;yield return Wait(1);_jump=true;yield return Wait(2);step="Slow replay";ReplayPlayer.Play(6,pc.me,.5f,"MECHANICS REPLAY",false);yield return Wait(14);if(ReplayPlayer.Active)ReplayPlayer.I.Stop();step="Free camera orbit";CameraTools.SetFree(true);var cam=Camera.main.transform;var center=Feet+Vector3.up;var offset=cam.position-center;for(int i=0;i<300;i++){cam.position=center+Quaternion.Euler(0,i*.5f,0)*offset;cam.LookAt(center);yield return null;}CameraTools.SetFree(false);yield return Wait(4);}
 static System.Collections.Generic.Dictionary<string,Vector2> UiSpots => typeof(Hud).GetField("Spots",BindingFlags.Public|BindingFlags.Static)?.GetValue(null) as System.Collections.Generic.Dictionary<string,Vector2> ?? new System.Collections.Generic.Dictionary<string,Vector2>();
 IEnumerator UiClick(string id){if(typeof(Hud).GetField("Spots",BindingFlags.Public|BindingFlags.Static)==null){if(id=="tab_LOCKER")typeof(Lobby).GetField("tab")?.SetValue(Lobby.I,1);else if(id=="tab_CAREER")typeof(Lobby).GetField("tab")?.SetValue(Lobby.I,2);else if(id=="tab_PLAY")typeof(Lobby).GetField("tab")?.SetValue(Lobby.I,0);else if(id.StartsWith("outfit_"))typeof(Lobby).GetMethod("Cycle")?.Invoke(Lobby.I,new object[]{int.Parse(id.Substring(7))==0?-1:1});else if(id.StartsWith("emote_"))Lobby.I.PlayEmote(int.Parse(id.Substring(6)));else if(id=="settings")Hud.SettingsOpen=true;else if(id=="back")Hud.SettingsOpen=false;else if(id.StartsWith("set_tab_"))typeof(Hud).GetField("_setTab",BindingFlags.NonPublic|BindingFlags.Instance)?.SetValue(FindFirstObjectByType<Hud>(),int.Parse(id.Substring(8)));yield return Wait(.6f);yield break;}for(int i=0;i<120&&!UiSpots.ContainsKey(id);i++)yield return null;if(!UiSpots.TryGetValue(id,out var q)){Debug.LogWarning("CAPTURE_UI_MISSING "+id);yield break;}var from=UiPointer.pos;for(int i=0;i<20;i++){UiPointer.pos=Vector2.Lerp(from,q,(i+1)/20f);yield return null;}UiPointer.click=true;yield return null;UiPointer.click=false;yield return Wait(.3f);}
 IEnumerator FrontendTake(Lobby lobby){step="Play screen";yield return Wait(5);yield return UiClick("tab_LOCKER");step="Locker and outfits";yield return Wait(4);yield return UiClick("slot_0");yield return Wait(3);yield return UiClick("outfit_1");yield return Wait(4);yield return UiClick("outfit_0");yield return Wait(3);yield return UiClick("slot_0");yield return UiClick("emote_2");step="Lobby emote";yield return Wait(8);yield return UiClick("tab_CAREER");step="Career";yield return Wait(5);yield return UiClick("tab_PLAY");yield return UiClick("settings");step="Settings";for(int i=0;i<4;i++){yield return UiClick("set_tab_"+i);yield return Wait(4);}yield return UiClick("back");yield return UiClick("change");step="Playlist selection";yield return Wait(5);}
}
